def cells(kind, position)
  state, x, y = position
  SHAPES[kind][state].map { |i, j| [x + i, y - j] }
def fits?(board, kind, position)
  cells(kind, position).all? { |c, r| c.between?(1, 10) && r.between?(1, 22) && (board[r - 1] & (1 << (c - 1))).zero? }
